-- Complete additive cloning of questionnaires, contract clause sets and service checklists.
create table public.content_clone_provenance(id uuid primary key default extensions.gen_random_uuid(),aggregate_type text not null check(aggregate_type in('QUESTIONNAIRE','CLAUSE_SET','CHECKLIST')),source_id uuid not null,target_id uuid not null,source_content_hash text not null check(source_content_hash~'^[0-9a-f]{64}$'),target_content_hash text not null check(target_content_hash~'^[0-9a-f]{64}$'),reason text not null check(length(btrim(reason))between 3 and 500),created_by uuid not null references auth.users(id),correlation_id uuid not null,created_at timestamptz not null default clock_timestamp(),unique(aggregate_type,target_id));
create table public.contract_clause_sets(id uuid primary key default extensions.gen_random_uuid(),code text not null unique check(code~'^[A-Z][A-Z0-9_-]{2,79}$'),current_version_id uuid,created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp());
create table public.contract_clause_set_versions(id uuid primary key default extensions.gen_random_uuid(),clause_set_id uuid not null references public.contract_clause_sets(id)on delete restrict,version integer not null check(version>0),clauses jsonb not null check(jsonb_typeof(clauses)='object'),content_hash text not null check(content_hash~'^[0-9a-f]{64}$'),source_contract_version_id uuid references public.contract_versions(id)on delete restrict,source_clause_set_version_id uuid references public.contract_clause_set_versions(id)on delete restrict,change_reason text not null check(length(btrim(change_reason))between 3 and 500),created_by uuid not null references auth.users(id),created_at timestamptz not null default clock_timestamp(),unique(clause_set_id,version),check(num_nonnulls(source_contract_version_id,source_clause_set_version_id)=1));
alter table public.contract_clause_sets add constraint contract_clause_sets_current_fk foreign key(current_version_id)references public.contract_clause_set_versions(id)on delete restrict;
do $$declare t text;begin foreach t in array array['content_clone_provenance','contract_clause_set_versions']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);execute format('create trigger %I before update or delete on public.%I for each row execute function private.prevent_update_delete()','clone_'||t||'_immutable',t);end loop;end$$;
alter table public.contract_clause_sets enable row level security;revoke all on public.contract_clause_sets from public,anon,authenticated,service_role;
grant select on public.content_clone_provenance,public.contract_clause_sets,public.contract_clause_set_versions to authenticated;
create policy clone_provenance_admin_read on public.content_clone_provenance for select to authenticated using(private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','LIBRARY_MANAGER','READ_ONLY_AUDITOR']));
create policy clause_sets_admin_read on public.contract_clause_sets for select to authenticated using(private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','LIBRARY_MANAGER','READ_ONLY_AUDITOR']));
create policy clause_set_versions_admin_read on public.contract_clause_set_versions for select to authenticated using(private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','LIBRARY_MANAGER','READ_ONLY_AUDITOR']));

create function public.clone_catalog_questionnaire(p_source_version_id uuid,p_target_release_id uuid,p_new_code text,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();src public.questionnaire_versions%rowtype;qid uuid;vid uuid;sid uuid;h text;cached jsonb;r jsonb;org uuid;sec record;
begin select*into src from public.questionnaire_versions where id=p_source_version_id;if a is null or not found or not private.has_library_permission(src.library_id,'CATALOG_EDIT',a)then raise exception'CATALOG_SCOPE_DENIED'using errcode='42501';end if;if src.sensitive and auth.jwt()->>'aal'is distinct from'aal2'then raise exception'CATALOG_SENSITIVE_MFA_REQUIRED'using errcode='42501';end if;if p_new_code!~'^[A-Z][A-Z0-9_-]{1,79}$'or length(btrim(coalesce(p_change_reason,'')))not between 3 and 500 or not exists(select 1 from public.catalog_releases where id=p_target_release_id and library_id=src.library_id and status in('DRAFT','IN_REVIEW','APPROVED'))then raise exception'INVALID_QUESTIONNAIRE_CLONE'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('operation','catalog.questionnaire.clone.v1','source',src.id,'release',p_target_release_id,'code',p_new_code,'reason',p_change_reason));select b.response_body into cached from private.begin_catalog_command(a,'catalog.questionnaire.clone',p_idempotency_key,h)b;if cached is not null then return cached;end if;insert into public.questionnaires(library_id,code,status,created_by)values(src.library_id,p_new_code,'DRAFT',a)returning id into qid;insert into public.questionnaire_versions(questionnaire_id,library_id,catalog_release_id,version,status,title_fr,title_ar,description_fr,description_ar,audience,engine_version,policy_version,snapshot_hash,sensitive,translation_review_status,change_reason,created_by)values(qid,src.library_id,p_target_release_id,1,'DRAFT',src.title_fr,src.title_ar,src.description_fr,src.description_ar,src.audience,src.engine_version,src.policy_version,src.snapshot_hash,src.sensitive,'PENDING',btrim(p_change_reason),a)returning id into vid;for sec in select*from public.questionnaire_sections where questionnaire_version_id=src.id order by sort_order loop insert into public.questionnaire_sections(questionnaire_version_id,section_key,label_fr,label_ar,help_fr,help_ar,sort_order,content_hash)values(vid,sec.section_key,sec.label_fr,sec.label_ar,sec.help_fr,sec.help_ar,sec.sort_order,sec.content_hash)returning id into sid;insert into public.questionnaire_version_questions(questionnaire_version_id,library_id,section_id,question_version_id,sort_order,required_override)select vid,src.library_id,sid,x.question_version_id,x.sort_order,x.required_override from public.questionnaire_version_questions x where x.questionnaire_version_id=src.id and x.section_id=sec.id;end loop;insert into public.questionnaire_version_rules(questionnaire_version_id,library_id,rule_version_id,evaluation_order)select vid,src.library_id,rule_version_id,evaluation_order from public.questionnaire_version_rules where questionnaire_version_id=src.id;h:=private.refresh_draft_questionnaire_snapshot(vid);update public.questionnaires set current_draft_version_id=vid where id=qid;insert into public.content_clone_provenance(aggregate_type,source_id,target_id,source_content_hash,target_content_hash,reason,created_by,correlation_id)values('QUESTIONNAIRE',src.id,vid,src.snapshot_hash,h,btrim(p_change_reason),a,p_correlation_id);select steward_organization_id into org from public.catalog_libraries where id=src.library_id;r:=jsonb_build_object('outcome','CATALOG_QUESTIONNAIRE_CLONED','questionnaire_id',qid,'version_id',vid,'snapshot_hash',h,'source_version_id',src.id);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(org,a,'USER','catalog.questionnaire.cloned','catalog_questionnaire',qid::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(org,'catalog_questionnaire',qid::text,'CatalogQuestionnaireClonedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_catalog_command(a,'catalog.questionnaire.clone',p_idempotency_key,r);return r;end$$;

create function public.clone_contract_clause_set(p_audit_organization_id uuid,p_source_type text,p_source_id uuid,p_new_code text,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();clauses jsonb;source_hash text;set_id uuid;version_id uuid;target_hash text;h text;cached jsonb;r jsonb;
begin if a is null or auth.jwt()->>'aal'is distinct from'aal2'or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','LIBRARY_MANAGER'],a)then raise exception'CLAUSE_SET_CLONE_DENIED'using errcode='42501';end if;if p_source_type='CONTRACT_VERSION'then select v.clauses,v.content_hash into clauses,source_hash from public.contract_versions v where v.id=p_source_id;elsif p_source_type='CLAUSE_SET_VERSION'then select v.clauses,v.content_hash into clauses,source_hash from public.contract_clause_set_versions v where v.id=p_source_id;else raise exception'INVALID_CLAUSE_SET_SOURCE'using errcode='22023';end if;if clauses is null or p_new_code!~'^[A-Z][A-Z0-9_-]{2,79}$'or length(btrim(coalesce(p_change_reason,'')))not between 3 and 500 or not exists(select 1 from public.organizations where id=p_audit_organization_id and status='ACTIVE')then raise exception'INVALID_CLAUSE_SET_CLONE'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('operation','contract.clause_set.clone.v1','source_type',p_source_type,'source_id',p_source_id,'code',p_new_code,'reason',p_change_reason));cached:=private.begin_contract_command(p_audit_organization_id,'contract.clause_set.clone',p_idempotency_key,h,a);if cached is not null then return cached;end if;target_hash:=private.canonical_request_hash(jsonb_build_object('code',p_new_code,'clauses',clauses,'source_hash',source_hash));insert into public.contract_clause_sets(code,created_by)values(p_new_code,a)returning id into set_id;insert into public.contract_clause_set_versions(clause_set_id,version,clauses,content_hash,source_contract_version_id,source_clause_set_version_id,change_reason,created_by)values(set_id,1,clauses,target_hash,case when p_source_type='CONTRACT_VERSION'then p_source_id end,case when p_source_type='CLAUSE_SET_VERSION'then p_source_id end,btrim(p_change_reason),a)returning id into version_id;update public.contract_clause_sets set current_version_id=version_id where id=set_id;insert into public.content_clone_provenance(aggregate_type,source_id,target_id,source_content_hash,target_content_hash,reason,created_by,correlation_id)values('CLAUSE_SET',p_source_id,version_id,source_hash,target_hash,btrim(p_change_reason),a,p_correlation_id);r:=jsonb_build_object('outcome','CONTRACT_CLAUSE_SET_CLONED','clause_set_id',set_id,'version_id',version_id,'content_hash',target_hash);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_audit_organization_id,a,'USER','contract.clause_set.cloned','contract_clause_set',set_id::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_audit_organization_id,'contract_clause_set',set_id::text,'ContractClauseSetClonedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_audit_organization_id,'contract.clause_set.clone',p_idempotency_key,r);return r;end$$;

create function public.clone_service_checklist(p_audit_organization_id uuid,p_source_template_id uuid,p_target_service_version_id uuid,p_change_reason text,p_idempotency_key text,p_correlation_id uuid default extensions.gen_random_uuid())returns jsonb language plpgsql security definer set search_path=pg_catalog,public,private,extensions as $$
declare a uuid:=auth.uid();src public.service_checklist_templates%rowtype;h text;cached jsonb;r jsonb;x uuid;v integer;target_hash text;
begin select*into src from public.service_checklist_templates where id=p_source_template_id;if a is null or auth.jwt()->>'aal'is distinct from'aal2'or not private.has_platform_role(array['SUPER_ADMIN','MATRICIA_ADMIN','LIBRARY_MANAGER'],a)then raise exception'CHECKLIST_CLONE_DENIED'using errcode='42501';end if;if not found or not exists(select 1 from public.catalog_service_versions where id=p_target_service_version_id)or length(btrim(coalesce(p_change_reason,'')))not between 3 and 500 then raise exception'INVALID_CHECKLIST_CLONE'using errcode='22023';end if;h:=private.canonical_request_hash(jsonb_build_object('operation','service.checklist.clone.v1','source',src.id,'target_service_version',p_target_service_version_id,'reason',p_change_reason));cached:=private.begin_contract_command(p_audit_organization_id,'service.checklist.clone',p_idempotency_key,h,a);if cached is not null then return cached;end if;select coalesce(max(version),0)+1 into v from public.service_checklist_templates where service_version_id=p_target_service_version_id;target_hash:=private.canonical_request_hash(jsonb_build_object('items',src.items,'target_service_version',p_target_service_version_id,'version',v));insert into public.service_checklist_templates(service_version_id,version,items,content_hash,created_by)values(p_target_service_version_id,v,src.items,target_hash,a)returning id into x;insert into public.content_clone_provenance(aggregate_type,source_id,target_id,source_content_hash,target_content_hash,reason,created_by,correlation_id)values('CHECKLIST',src.id,x,src.content_hash,target_hash,btrim(p_change_reason),a,p_correlation_id);r:=jsonb_build_object('outcome','SERVICE_CHECKLIST_CLONED','template_id',x,'version',v,'content_hash',target_hash);insert into public.audit_events(organization_id,actor_user_id,actor_type,action,resource_type,resource_id,correlation_id,metadata,event_hash)values(p_audit_organization_id,a,'USER','service.checklist.cloned','service_checklist_template',x::text,p_correlation_id,r,repeat('0',64));insert into public.event_outbox(organization_id,aggregate_type,aggregate_id,event_type,correlation_id,payload,idempotency_key)values(p_audit_organization_id,'service_checklist_template',x::text,'ServiceChecklistClonedV1',p_correlation_id,r,p_idempotency_key);perform private.finish_contract_command(p_audit_organization_id,'service.checklist.clone',p_idempotency_key,r);return r;end$$;
revoke all on function public.clone_catalog_questionnaire(uuid,uuid,text,text,text,uuid),public.clone_contract_clause_set(uuid,text,uuid,text,text,text,uuid),public.clone_service_checklist(uuid,uuid,uuid,text,text,uuid)from public,anon,authenticated,service_role;
grant execute on function public.clone_catalog_questionnaire(uuid,uuid,text,text,text,uuid),public.clone_contract_clause_set(uuid,text,uuid,text,text,text,uuid),public.clone_service_checklist(uuid,uuid,uuid,text,text,uuid)to authenticated;
